import{_ as i,C as d,o as s,c as l,j as t,a as r,E as a,a2 as n}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Deliver","description":"","frontmatter":{"title":"Deliver"},"headers":[],"relativePath":"en/agent/livrer.md","filePath":"en/agent/livrer.md"}'),c={name:"en/agent/livrer.md"};function h(u,e,f,p,m,g){const o=d("Ask");return s(),l("div",null,[e[0]||(e[0]=t("h1",{id:"deliver",tabindex:"-1"},[r("Deliver "),t("a",{class:"header-anchor",href:"#deliver","aria-label":'Permalink to "Deliver"'},"​")],-1)),e[1]||(e[1]=t("p",null,"This path is for delivering a new version, of the whole project or of a single module, and then publishing it on the public channel. You come here when a version is ready and you want the agent to run the delivery for you.",-1)),e[2]||(e[2]=t("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[r("What you ask the agent "),t("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),a(o,{say:"Prepare the delivery of the site module as a patch and show me the plan.",verb:"effortless_release_plan",family:"livraison",args:'{"bump":"patch","stack":"site"}'}),a(o,{say:"What would the tag be if we delivered the whole project as a minor?",verb:"effortless_release_plan",family:"livraison",args:'{"bump":"minor"}'}),a(o,{say:"Set up delivery of the site module: build with pnpm build, artifacts in dist/*.zip.",verb:"effortless_release_delivery_set",family:"livraison",args:'{"stack":"site","build_command":"pnpm build","artifacts":"dist/*.zip"}'}),a(o,{say:"Turn on the tag and the documentation update in the release configuration.",verb:"effortless_release_config_set",family:"livraison",args:'{"tag":true,"update_docs":true}'}),a(o,{say:"Declare acme/site-dev as the internal repository and acme/site as the public one for the site module.",verb:"effortless_release_channels_set",family:"livraison",args:'{"stack":"site","internal":"acme/site-dev","public":"acme/site"}'}),a(o,{say:"Deliver the site module: bump the version, commit and push, tag, build and artifacts.",verb:"effortless_release_apply",family:"livraison",args:'{"steps":"bump_version,git_flow,tag_release,delivery","stack":"site"}'}),e[3]||(e[3]=t("p",null,[t("em",null,"(the agent asks for your agreement first)")],-1)),a(o,{say:"Publish the site-v1.4.1 version, already delivered internally, to the public channel.",verb:"effortless_release_promote",family:"livraison",args:'{"stack":"site","tag":"site-v1.4.1","confirm":"site-v1.4.1"}'}),e[4]||(e[4]=t("p",null,[t("em",null,"(the agent asks for your agreement first)")],-1)),a(o,{say:"Show me the delivery history.",verb:"effortless_deliveries",family:"livraison"}),e[5]||(e[5]=n('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="plan-a-delivery" tabindex="-1">Plan a delivery <a class="header-anchor" href="#plan-a-delivery" aria-label="Permalink to &quot;Plan a delivery&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#release-plan"><code>effortless_release_plan</code></a> computes the plan without writing anything: current and target version, tag, repository, branch, version files. <code>bump</code> is <code>patch</code> (default), <code>minor</code> or <code>major</code>. <code>stack</code> targets a module; without <code>stack</code>, the plan covers the whole project.</li><li>The tag depends on the target: <code>vX.Y.Z</code> for the whole project or for a module with its own repository, <code>&lt;module&gt;-vX.Y.Z</code> for a module that lives in the project&#39;s repository.</li></ol><h3 id="configure-the-delivery" tabindex="-1">Configure the delivery <a class="header-anchor" href="#configure-the-delivery" aria-label="Permalink to &quot;Configure the delivery&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#release-config-show"><code>effortless_release_config_show</code></a> reads the effective release configuration.</li><li><a href="/Effortless/en/reference/mcp/livraison.html#release-config-set"><code>effortless_release_config_set</code></a> sets three options: <code>git_flow</code> (commit and push step), <code>tag</code> (tag creation) and <code>update_docs</code> (documentation update). At least one is required.</li><li><a href="/Effortless/en/reference/mcp/livraison.html#release-delivery-set"><code>effortless_release_delivery_set</code></a> records, for a module (or <code>default</code>), the build command (<code>build_command</code>) and the artifacts to upload (<code>artifacts</code>, comma-separated globs). Without <code>artifacts</code>, the ones already recorded are kept. An undeclared module is refused.</li></ol><h3 id="run-the-delivery" tabindex="-1">Run the delivery <a class="header-anchor" href="#run-the-delivery" aria-label="Permalink to &quot;Run the delivery&quot;">​</a></h3><p>This step acts for real: version files are written, then commit, push, tag, GitHub release, build. The agent runs it <strong>only after your explicit agreement</strong>.</p><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#release-apply"><code>effortless_release_apply</code></a> takes <code>steps</code> (among <code>bump_version</code>, <code>git_flow</code>, <code>tag_release</code>, <code>update_docs</code>, <code>delivery</code>), <code>bump</code> and, for a module, <code>stack</code>.</li><li>Steps always run in that order. A failing step stops the chain: the following ones are reported as &quot;not run&quot;. A step the engine cannot do (for example without <code>gh</code>) is reported as &quot;to do by hand&quot;, with what remains to be done.</li><li><strong>Bump the version</strong> checks every version file before writing any. <strong>Commit and push</strong> only merges onto the main branch by fast-forward. <strong>Tag and GitHub release</strong> refuses to place a tag on uncommitted files: the tag would point at the previous commit, without the new version.</li><li>The agent reads the result step by step and summarizes it for you.</li></ol><h3 id="declare-the-internal-and-public-channels" tabindex="-1">Declare the internal and public channels <a class="header-anchor" href="#declare-the-internal-and-public-channels" aria-label="Permalink to &quot;Declare the internal and public channels&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#release-channels-set"><code>effortless_release_channels_set</code></a> sets the two release repositories of a target (<code>stack</code>, or <code>default</code> for the whole project): <code>internal</code> (empty = the origin repository) and <code>public</code> (empty = no public channel). An omitted parameter is left unchanged. A repository is written <code>owner/name</code>.</li></ol><h3 id="publish-publicly" tabindex="-1">Publish publicly <a class="header-anchor" href="#publish-publicly" aria-label="Permalink to &quot;Publish publicly&quot;">​</a></h3><p>Public publication <strong>promotes</strong> a version already delivered internally, as it is: same tag, same artifacts, no new bump. It cannot be undone. The agent starts it <strong>only after your explicit agreement</strong>.</p><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#release-promote"><code>effortless_release_promote</code></a> takes <code>tag</code> (the tag already delivered internally), <code>stack</code> for a module, and <code>confirm</code>, which must repeat exactly the same tag.</li><li>The engine downloads the internal release, republishes it on the public repository and records the publication in the journal.</li></ol><h3 id="read-the-history" tabindex="-1">Read the history <a class="header-anchor" href="#read-the-history" aria-label="Permalink to &quot;Read the history&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/livraison.html#deliveries"><code>effortless_deliveries</code></a> returns the delivery journal, most recent first: date, channel, module, tag, version, repository, outcome. It also returns the channels of each target. It needs no network.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Version files at the new value, a commit, an annotated tag and, if the repository is on GitHub and <code>gh</code> is available, a release with its artifacts.</li><li>Every delivery, successful or stopped, and every publication, is recorded in <code>.effortless/deliveries.json</code>, versioned with the project.</li><li>In the app, the <a href="/Effortless/en/guide/release.html">Delivery</a> screen shows the same plan, configuration, channels and the <strong>Delivery history</strong>.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>The project is in semi-auto mode</td><td><code>release_apply</code> returns an &quot;execution tool disabled&quot; message (flagged <code>gated</code>); <code>release_promote</code> is refused with <code>release:gated</code></td><td>Switch the project to full mode, then ask for the delivery again.</td></tr><tr><td>The module does not exist</td><td><code>release:unknownModule</code> (plan, execution, channels); <code>deploiement:stackUnknown</code> for the delivery configuration</td><td>Pass the id of a declared module, or <code>default</code> / no <code>stack</code> for the whole project.</td></tr><tr><td>No step selected</td><td><code>deploiement:noStepSelected</code></td><td>Pick at least one valid step in <code>steps</code> (unknown ids are ignored).</td></tr><tr><td>A step fails during execution</td><td><code>deploiement:applyStopped</code>, with the failing step&#39;s detail</td><td>Fix the cause named in the detail, then run again. Steps already done are not undone.</td></tr><tr><td>Tag requested while files are uncommitted</td><td><code>tag_release</code> step fails: &quot;Tag … not placed&quot;</td><td>Replay with the <code>git_flow</code> step, or commit first.</td></tr><tr><td><code>release_config_set</code> with no option</td><td><code>deploiement:configNoField</code></td><td>Pass at least <code>git_flow</code>, <code>tag</code> or <code>update_docs</code>.</td></tr><tr><td>Delivery configuration without a module</td><td><code>deploiement:stackRequired</code></td><td>Pass <code>stack</code>; <code>effortless_stack_list</code> names the declared ones.</td></tr><tr><td>Badly written repository</td><td><code>release:repoInvalid</code></td><td>Write the repository as <code>owner/name</code>, or an empty value to remove the channel.</td></tr><tr><td>No public repository declared</td><td><code>release:noPublicChannel</code></td><td>Declare it with <code>effortless_release_channels_set</code>.</td></tr><tr><td><code>confirm</code> differs from the tag</td><td><code>release:confirmMismatch</code></td><td>Give back exactly the tag, after your explicit agreement.</td></tr><tr><td>The version was not delivered internally</td><td><code>release:notInternal</code></td><td>Deliver the version internally first (&quot;Tag and GitHub release&quot; step).</td></tr><tr><td>The version is already public</td><td><code>release:alreadyPublic</code></td><td>Nothing to do. For a new version, deliver it internally first.</td></tr><tr><td><code>gh</code> missing or failing during a publication</td><td><code>release:ghMissing</code> or <code>release:ghFailed</code></td><td>Install <code>gh</code> and sign in, then run again.</td></tr></tbody></table>',19))])}const b=i(c,[["render",h]]);export{v as __pageData,b as default};
